from dataclasses import dataclass

@dataclass(frozen=True)
class Shipment:
    identifier: str
    weights: tuple[int, ...]

    def __post_init__(self):
        if type(self.identifier) is not str:
            raise TypeError('identifier must be str')
        name = self.identifier.strip()
        if not name:
            raise ValueError('identifier must not be blank')
        weights = tuple(self.weights)
        if not weights or any(type(value) is not int or value <= 0 for value in weights):
            raise ValueError('weights must contain positive integers, excluding bool')
        object.__setattr__(self, 'identifier', name)
        object.__setattr__(self, 'weights', weights)

from typing import Protocol

class QuoteProvider(Protocol):
    def quote(self, shipment: Shipment) -> int:
        ...

def quote_batch(shipments: list[Shipment], provider: QuoteProvider) -> list[tuple[str, int]]:
    result = []
    for shipment in shipments:
        cents = provider.quote(shipment)
        if type(cents) is not int or cents < 0:
            raise ValueError('provider must return nonnegative integer cents')
        result.append((shipment.identifier, cents))
    return result

