import json

class OrderFormatError(ValueError):
    def __init__(self, line_number):
        self.line_number = line_number
        super().__init__(f'invalid order on line {line_number}')

def stream_orders(open_source):
    source = open_source()
    try:
        for line_number, line in enumerate(source, 1):
            if not line.strip():
                continue
            try:
                record = json.loads(line)
                if type(record) is not dict or set(record) != {'id', 'qty'}:
                    raise ValueError('expected id and qty')
                if type(record['id']) is not str or not record['id'].strip():
                    raise ValueError('id must be nonblank str')
                if type(record['qty']) is not int or record['qty'] <= 0:
                    raise ValueError('qty must be a positive integer')
            except ValueError as error:
                raise OrderFormatError(line_number) from error
            yield record
    finally:
        source.close()

def take_matching(open_source, predicate, limit):
    if type(limit) is not int or limit < 0:
        raise ValueError('limit must be a nonnegative integer')
    if limit == 0:
        return
    orders = stream_orders(open_source)
    count = 0
    try:
        for order in orders:
            if predicate(order):
                count += 1
                if count == limit:
                    orders.close()
                    yield order
                    return
                yield order
    finally:
        orders.close()

